"""Generated Tier-A conformance suite.

The bridge emits one parametrized pytest module under
tests/dspy_gate/generated/. The Tier-A case list is baked in from the
manifest, so the bytes are deterministic and a stale module differs
from its regeneration. A judged-only scenario emits no test, so the
root suite stays green with no network and no model call.
"""

import json
from pprint import pformat
from pathlib import Path

HEADER = (
    '"""GENERATED by python -m dspy_gate regen; edit the spec, not this file.\n'
    "\n"
    "Gate 3 conformance suite: one test per scenario with Tier-A assertions.\n"
    "A failure names the scenario it violates. Judged-only scenarios run in\n"
    "the gate runner, never here, so this module needs no network.\n"
    '"""\n'
    "\n"
    "import pytest\n"
    "\n"
    "from dspy_gate import checks, harness\n"
    "\n"
    "CASES = "
)

BODY = '''

@pytest.mark.parametrize("case", CASES, ids=lambda c: c["scenario_id"])
def test_scenario_conformance(case):
    pred, trace = harness.run(case)
    result = checks.run_tier_a(case["checks"], pred, trace)
    assert result.passed, (
        f"scenario {case['scenario_id']} failed tier A: {result.detail}"
    )
'''


def _tier_a_cases(manifest_data):
    """Return the baked case records, manifest order preserved."""
    cases = []
    for change in manifest_data["changes"].values():
        for case in change["eval_cases"]:
            if case["surface"] == "dspy-eval" and any(
                c["tier"] == "A" for c in case["checks"]
            ):
                cases.append(case)
    return cases


def generate(manifest_data):
    """Render the conformance module from one manifest dict."""
    cases = _tier_a_cases(manifest_data)
    return HEADER + pformat(cases, sort_dicts=True, width=88) + BODY


def write(generated_root, content):
    """Write the module into the generated area and return its path."""
    path = Path(generated_root) / "test_spec_conformance.py"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    return path
